-- Generated from the checked saved game image. No automatic activation.
local ffi=require('ffi')
local guards={{0x4af4e0,""},{0x4af390,""},{0x4dec30,""},{0x4f3fa0,""},{0x5b36c0,""},{0x5b34f0,""},{0x84eee0,""},{0xfd97e0,""},{0xbb009,"f30f101d17be3002f30f1015c7c13002f30f100d33c53002e80a3c4200"},{0x23c7554,"00002041"},{0x23c71e0,"00002040"},{0x23c6e28,"9a99993f"}}
local M={}
local function bind(reader,base)
    assert(ffi.os=='Windows' and ffi.abi('64bit'),'Windows x64 required')
    assert(type(reader)=='function' and type(base)=='number' and base>=65536
        and base%4096==0 and base+0x3500000<2^47,'game base bound')
    for _,g in ipairs(guards) do
        local expected=g[2]:gsub('..',function(b) return string.char(tonumber(b,16)) end)
        assert(reader(base+g[1],#expected)==expected,'native operation signature mismatch')
    end
    return {clear=ffi.cast('void (*)(void **, const void *)',base+0x4af4e0),
        orbit=ffi.cast('void (*)(void **, float, float, float)',base+0x4dec30)}
end
function M.bind(reader,base,validate_scope)
    assert(type(validate_scope)=='function' and validate_scope()==true,'held native scope required')
    local calls=bind(reader,base)
    assert(validate_scope()==true,'scope expired while binding')
    return calls
end
-- Signature-checked function pointers only; explicitly grants no lifetime lease.
function M.bind_experimental(reader,base) return bind(reader,base) end
return M
